#!/usr/bin/env python3
"""Read-only literal search using Python 3.9+ and the standard library."""
import json
import os
from pathlib import Path
import stat
import sys


def _within(path, root):
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def _raise(error):
    raise error


def search(data):
    """Return matching lines, or {'error': 'invalid_input'}."""
    invalid = {'error': 'invalid_input'}
    if not isinstance(data, dict) or set(data) != {'root', 'query', 'path'}:
        return invalid
    if any(not isinstance(data[key], str) for key in data):
        return invalid
    if not data['root'] or not data['path'] or not data['query']:
        return invalid
    if '\x00' in data['root'] or '\x00' in data['path']:
        return invalid

    try:
        root = Path(data['root']).resolve(strict=True)
        if not root.is_dir():
            return invalid
        target = (root / data['path']).resolve(strict=True)
        if not _within(target, root):
            return invalid
        mode = target.stat().st_mode
        if stat.S_ISREG(mode):
            candidates = [target]
        elif stat.S_ISDIR(mode):
            candidates = []
            for directory, dirs, files in os.walk(
                target, followlinks=False, onerror=_raise
            ):
                base = Path(directory)
                dirs[:] = sorted(
                    name for name in dirs if not (base / name).is_symlink()
                )
                candidates.extend(base / name for name in sorted(files))
        else:
            return invalid

        matches = []
        for candidate in candidates:
            # Do not follow symlinks discovered while walking.
            if candidate.is_symlink():
                continue
            resolved = candidate.resolve(strict=True)
            if not _within(resolved, root):
                return invalid
            if not stat.S_ISREG(resolved.stat().st_mode):
                continue
            try:
                # Decode the entire file before recording any matches.
                content = resolved.read_bytes().decode('utf-8')
            except UnicodeDecodeError:
                continue
            relative = resolved.relative_to(root).as_posix()
            # Treat LF, CRLF and CR as line endings; preserve other characters.
            content = content.replace('\r\n', '\n').replace('\r', '\n')
            lines = content.split('\n')
            if lines and lines[-1] == '':
                lines.pop()
            for number, line in enumerate(lines, 1):
                if data['query'] in line:
                    matches.append({'path': relative, 'line': number, 'text': line})
        matches.sort(key=lambda match: (match['path'], match['line']))
        return {'matches': matches}
    except (OSError, ValueError, RuntimeError):
        return invalid


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('Duplicate JSON key')
        result[key] = value
    return result


def _reject_constant(value):
    raise ValueError('Invalid JSON constant')


def main():
    try:
        data = json.loads(
            sys.stdin.buffer.read().decode('utf-8'),
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
        result = search(data)
    except (ValueError, OSError, RecursionError):
        result = {'error': 'invalid_input'}
    sys.stdout.write(json.dumps(result, ensure_ascii=True) + '\n')


if __name__ == '__main__':
    main()
